trait OrderPort { def place(order: Order): Either[Rejected, Receipt] }

final class LegacyOrderAdapter(client: LegacyClient) extends OrderPort:
  def place(order: Order): Either[Rejected, Receipt] =
    client.submit(LegacyOrderDto.from(order))        // translate out
      .toEither.left.map(Rejected.from)              // Try/Either -> local error
      .flatMap(resp => Receipt.fromLegacy(resp))     // translate back, fallible

object Order:
  def fromLegacy(dto: LegacyOrderDto): Either[Rejected, Order] =
    if dto.qty <= 0 then Left(Rejected("quantity must be positive"))
    else Right(Order(dto.orderId, dto.qty))
